import sys
from array import array


def read_ints():
    data = sys.stdin.buffer.read()
    value = 0
    for c in data:
        if 48 <= c <= 57:
            value = value * 10 + c - 48
        elif value:
            yield value
            value = 0
    if value:
        yield value


it = read_ints()
n = next(it)
k = next(it)

graph = [[] for _ in range(n)]
for _ in range(n - 1):
    a = next(it) - 1
    b = next(it) - 1
    graph[a].append(b)
    graph[b].append(a)
del it

parent = array('i', [-1]) * n
depth = array('i', [0]) * n
parent[0] = 0
order = [0]
stack = [0]

while stack:
    v = stack.pop()
    for w in graph[v]:
        if w != parent[v]:
            parent[w] = v
            depth[w] = depth[v] + 1
            stack.append(w)
            order.append(w)

nodes = sorted(order, key=depth.__getitem__, reverse=True)

levels = n.bit_length() + 1
centroid_table = array('i', [0]) * (levels * n)
distance_table = array('i', [0]) * (levels * n)
centroid_depth = bytearray(n)
removed = bytearray(n)
work_parent = array('i', [-1]) * n
subtree_size = array('i', [0]) * n


def decompose(start, level):
    component = []
    todo = [start]
    work_parent[start] = -1

    while todo:
        v = todo.pop()
        component.append(v)
        for w in graph[v]:
            if not removed[w] and w != work_parent[v]:
                work_parent[w] = v
                todo.append(w)

    for v in component:
        subtree_size[v] = 1
    for v in reversed(component):
        p = work_parent[v]
        if p != -1:
            subtree_size[p] += subtree_size[v]

    total = len(component)
    centroid = component[0]
    best_part = total + 1

    for v in component:
        largest = total - subtree_size[v]
        for w in graph[v]:
            if not removed[w] and work_parent[w] == v:
                if subtree_size[w] > largest:
                    largest = subtree_size[w]
        if largest < best_part:
            best_part = largest
            centroid = v

    base = level * n
    todo = [(centroid, -1, 0)]
    while todo:
        v, p, dist = todo.pop()
        idx = base + v
        centroid_table[idx] = centroid
        distance_table[idx] = dist
        centroid_depth[v] = level
        for w in graph[v]:
            if not removed[w] and w != p:
                todo.append((w, v, dist + 1))

    removed[centroid] = 1
    for w in graph[centroid]:
        if not removed[w]:
            decompose(w, level + 1)


decompose(0, 0)

log = n.bit_length()
ancestor = array('i', [0]) * (log * n)
ancestor[:n] = parent
for j in range(1, log):
    prev = (j - 1) * n
    cur = j * n
    for v in range(n):
        ancestor[cur + v] = ancestor[prev + ancestor[prev + v]]

best_distance = [n + 1] * n


def feasible(radius):
    used = 0
    bits = [j for j in range(log) if (radius >> j) & 1]

    for v in nodes:
        covered = False
        for level in range(centroid_depth[v] + 1):
            idx = level * n + v
            c = centroid_table[idx]
            if best_distance[c] + distance_table[idx] <= radius:
                covered = True
                break

        if covered:
            continue

        used += 1
        if used > k:
            return False

        center = v
        for bit in bits:
            center = ancestor[bit * n + center]

        for level in range(centroid_depth[center] + 1):
            idx = level * n + center
            c = centroid_table[idx]
            dist = distance_table[idx]
            if dist < best_distance[c]:
                best_distance[c] = dist

    return True


low, high = -1, n - 1
while high - low > 1:
    mid = (low + high) // 2
    if feasible(mid):
        high = mid
    else:
        low = mid

print(high)
